/** Friendly alternate names -> curated names. */
export const ICON_ALIASES = {
  "add": "plus",
  "cart": "shopping-cart",
  "chart": "bar-chart-3",
  "chat": "message-circle",
  "close": "x",
  "dashboard": "layout-dashboard",
  "delete": "trash-2",
  "edit": "edit-3",
  "food": "utensils",
  "gym": "dumbbell",
  "money": "dollar-sign",
  "money-bag": "wallet",
  "profile": "user",
  "school": "graduation-cap",
  "team": "users",
};

export const ICON_NAMES = Object.keys(ICONS);

/** The element list for a curated name or alias (any case, spaces or underscores for hyphens), else null. */
export function iconData(name) {
  const key = String(name ?? "").trim().toLowerCase().replace(/[\s_]+/g, "-");
  const hit = Object.hasOwn(ICONS, key) ? key : Object.hasOwn(ICON_ALIASES, key) ? ICON_ALIASES[key] : "";
  return hit ? ICONS[hit] : null;
}
